<?php
require_once __DIR__.'/includes/panel_helpers.php';exigirRol([1]);require_once __DIR__.'/../config/database.php';if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));$config=null;$error=null;
try{$pdo=conectarBD();$config=$pdo->query('SELECT * FROM configuracion_pagos WHERE id=1')->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){$token=$_POST['csrf_token']??'';if(!is_string($token)||!hash_equals($_SESSION['csrf_token'],$token)){http_response_code(403);exit('Solicitud no válida.');}$banco=trim((string)($_POST['banco']??''));$titular=trim((string)($_POST['titular']??''));$instrucciones=trim((string)($_POST['instrucciones']??''));if($banco===''||$titular===''||mb_strlen($banco)>120||mb_strlen($titular)>160||mb_strlen($instrucciones)>500)$error='Completa correctamente los datos bancarios.';
else{$ruta=$config['qr_imagen']??null;if(isset($_FILES['qr'])&&($_FILES['qr']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$archivo=$_FILES['qr'];if($archivo['error']!==UPLOAD_ERR_OK||$archivo['size']>2*1024*1024)throw new RuntimeException('El archivo supera 2 MB o no pudo cargarse.');$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($archivo['tmp_name']);$extensiones=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'];if(!isset($extensiones[$mime])||getimagesize($archivo['tmp_name'])===false)throw new RuntimeException('El QR debe ser una imagen PNG, JPG o WebP válida.');$carpeta=__DIR__.'/uploads/payment_qr';if(!is_dir($carpeta)&&!mkdir($carpeta,0755,true))throw new RuntimeException('No se pudo preparar la carpeta de imágenes.');$nombre='qr-'.bin2hex(random_bytes(12)).'.'.$extensiones[$mime];if(!move_uploaded_file($archivo['tmp_name'],$carpeta.'/'.$nombre))throw new RuntimeException('No se pudo guardar la imagen.');$ruta='uploads/payment_qr/'.$nombre;}
$s=$pdo->prepare('UPDATE configuracion_pagos SET banco=:banco,titular=:titular,instrucciones=:instrucciones,qr_imagen=:qr,actualizado_por=:usuario,updated_at=now() WHERE id=1');$s->execute(['banco'=>$banco,'titular'=>$titular,'instrucciones'=>$instrucciones!==''?$instrucciones:null,'qr'=>$ruta,'usuario'=>$_SESSION['usuario_id']]);$_SESSION['csrf_token']=bin2hex(random_bytes(32));header('Location: configurar_metodos_pago.php?actualizado=1');exit;}}
}catch(Throwable $e){error_log($e->getMessage());$error=$e instanceof RuntimeException?$e->getMessage():'No se pudo actualizar la configuración.';}
require_once __DIR__.'/includes/layout.php';renderSidebar('pagos');?>
<div class="payment-form-shell"><div class="doctor-page-heading"><div><span class="doctor-eyebrow">Configuración administrativa</span><h1>QR de la clínica</h1><p>Sube o reemplaza la imagen que verán los pacientes al elegir pago mediante QR.</p></div><a class="btn btn-secondary" href="pagos.php">Volver a pagos</a></div><?php if(isset($_GET['actualizado'])):?><div class="alert alert-success">El QR y los datos bancarios se actualizaron correctamente.</div><?php endif;?><?php if($error):?><div class="alert alert-error"><?= h($error) ?></div><?php endif;?><div class="payment-form-grid"><section class="card"><div class="card-header"><div><h2 class="card-title">Vista para el paciente</h2><p class="card-subtitle">Así aparecerá en Métodos de pago</p></div></div><div class="card-body qr-preview"><?php if(!empty($config['qr_imagen'])):?><img id="qr-preview-image" src="<?= h($config['qr_imagen']) ?>" alt="QR bancario de Clínica Vida Salud"><?php else:?><img id="qr-preview-image" src="" alt="Vista previa del QR" hidden><div class="qr-placeholder" id="qr-empty-preview"><?= icono('agenda') ?><strong>QR no configurado</strong><span>Selecciona una imagen para ver la vista previa.</span></div><?php endif;?><strong><?= h($config['banco']??'Banco no configurado') ?></strong><span><?= h($config['titular']??'') ?></span></div></section><section class="card"><div class="card-header"><div><h2 class="card-title">Subir QR bancario</h2><p class="card-subtitle">Solo el administrador puede modificarlo</p></div></div><div class="card-body"><form method="POST" enctype="multipart/form-data" class="stack"><input type="hidden" name="csrf_token" value="<?= h($_SESSION['csrf_token']) ?>"><div class="form-group"><label class="form-label required" for="banco">Banco o entidad</label><input class="form-input" id="banco" name="banco" maxlength="120" required value="<?= h($config['banco']??'') ?>" placeholder="Ej.: Banco Nacional"></div><div class="form-group"><label class="form-label required" for="titular">Titular de la cuenta</label><input class="form-input" id="titular" name="titular" maxlength="160" required value="<?= h($config['titular']??'') ?>" placeholder="Nombre del titular"></div><div class="form-group"><label class="form-label" for="instrucciones">Instrucciones para el paciente</label><textarea class="form-textarea" id="instrucciones" name="instrucciones" maxlength="500" rows="3" placeholder="Ej.: Escanea el QR y presenta tu comprobante en recepción."><?= h($config['instrucciones']??'') ?></textarea></div><div class="form-group"><span class="form-label">Imagen del QR</span><label class="qr-upload-zone" for="qr"><?= icono('agenda') ?><span><strong>Haz clic para subir una imagen</strong><small id="qr-file-name">PNG, JPG o WebP · Máximo 2 MB</small></span><em>Elegir imagen</em></label><input class="visually-hidden-file" id="qr" type="file" name="qr" accept="image/png,image/jpeg,image/webp"><small class="form-hint">Si no eliges otra imagen, se conservará el QR actual.</small></div><button class="btn btn-primary qr-save-button" type="submit"><?= icono('atendida') ?> Guardar QR de la clínica</button></form></div></section></div></div><script>document.addEventListener('DOMContentLoaded',()=>{const input=document.getElementById('qr'),name=document.getElementById('qr-file-name'),preview=document.getElementById('qr-preview-image'),empty=document.getElementById('qr-empty-preview');input.addEventListener('change',()=>{const file=input.files&&input.files[0];if(!file)return;if(file.size>2*1024*1024){input.value='';name.textContent='La imagen supera el límite de 2 MB';return;}name.textContent=file.name;preview.src=URL.createObjectURL(file);preview.hidden=false;if(empty)empty.hidden=true;});});</script><?php renderFooter();?>
